"""26-circle packing."""
import numpy as np

def construct_packing():
    n = 26
    centers = np.zeros((n, 2))
    radii_arr = np.zeros(n)

    cx, cy, r = 0.5, 0.5, 0.175
    centers[0] = [cx, cy]
    radii_arr[0] = r
    existing = [(cx, cy, r)]

    for cx, cy in [(0.09, 0.09), (0.91, 0.09), (0.09, 0.91), (0.91, 0.91)]:
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    for cx, cy in [(0.5, 0.12), (0.5, 0.88), (0.12, 0.5), (0.88, 0.5)]:
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    for cx, cy in [(0.15, 0.15), (0.85, 0.15), (0.15, 0.85), (0.85, 0.85)]:
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    for cx, cy in [(0.3, 0.3), (0.7, 0.3), (0.3, 0.7), (0.7, 0.7)]:
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    for cx, cy in [(0.4, 0.4), (0.6, 0.6), (0.45, 0.45), (0.2, 0.2), (0.8, 0.8)]:
        if len(existing) >= n:
            break
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    for cx, cy in [(0.25, 0.25), (0.75, 0.75)]:
        if len(existing) >= n:
            break
        rr = max_possible_radius(cx, cy, existing)
        if rr > 0:
            idx = len(existing)
            centers[idx] = [cx, cy]
            radii_arr[idx] = rr
            existing.append((cx, cy, rr))

    return centers, radii_arr, np.sum(radii_arr)

def max_possible_radius(x, y, existing):
    r = min(x, y, 1.0 - x, 1.0 - y)
    for ex, ey, er in existing:
        d = np.sqrt((x - ex)**2 + **(y - ey)2)
        r = min(r, d - er)
    return max(0.0, r)

